import json, re
from collections import Counter
from html.parser import HTMLParser
from html import unescape
s=json.load(open('source.json')); a=json.load(open('answer.json')); r=json.load(open('reference-targets.json'))
class P(HTMLParser):
 def __init__(self): super().__init__(convert_charrefs=True); self.x=[]
 def handle_starttag(self,t,attrs):
  if t in ['p','br','div','li','tr']: self.x.append(' ')
 def handle_endtag(self,t):
  if t in ['p','div','li','tr']: self.x.append(' ')
 def handle_data(self,t): self.x.append(t)
def plain(t):
 p=P();p.feed(t or '');return re.sub(r'\\s+',' ',''.join(p.x)).strip()
allowed=set('p br table thead tbody tfoot tr th td b strong i em u sup sub ul ol li div span blockquote'.split())
class Tags(HTMLParser):
 def handle_starttag(self,t,attrs):
  assert t in allowed, t
  for k,v in attrs: assert k in ['rowspan','colspan'] and re.fullmatch('[0-9]+',v)
required='code_id source_id source_sha256 number proposed_xml reason review_notes status substantive_impact'.split()
classifications=set('material_reduction coordination_only retained_necessary financing_transfer payment_timing_relief mixed reserved editorial_only'.split())
kinds=set('tax_removed tax_reduced obligation_removed obligation_merged authorization_removed regime_merged deadline_reduced compliance_cost_reduced tax_increased obligation_added deadline_increased complexity_added financing_transfer payment_deferred relief_extended relief_preserved coordination'.split())
units=set('percent euro legal_duty regime calendar_days working_days financing other'.split())
assert len(s)==len(a)==24
for src,out in zip(s,a):
 assert all(k in out for k in required), out['number']
 for k in ['code_id','source_id','source_sha256','number']: assert out[k]==src[k]
 x=out['substantive_impact']; assert x['version']==1 and x['classification'] in classifications
 for k in ['assessment','scope_limitations','new_burdens_review']: assert len(x[k])>=40
 if src.get('benefit_check_required'): assert len(out['benefit_review'])>=100
 if out['status']=='retained_unchanged':
  assert out['proposed_xml'] is None and out['classification']=='retained_necessary'
  assert x['classification']=='retained_necessary' and x['effects']==[]
 else:
  assert out['status']=='rewrite_draft' and out['proposed_xml'];Tags().feed(out['proposed_xml'])
 if out.get('change_type')=='normative_reduction':
  assert out['reform_policy_id']=='editorial_direction_2026_10_19'
  assert out['removed_provisions'] and all(len(v)>=30 for v in out['removed_provisions'])
 for e in x['effects']:
  assert set(e)==set('kind measure_id description before after unit affected_population conditions_and_transition replacement_or_new_burdens source_quote proposed_quote'.split())
  assert e['kind'] in kinds and e['unit'] in units
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
  for k,body in [('source_quote',src['source_xml']),('proposed_quote',out['proposed_xml'])]:
   assert len(e[k])>=12 and e[k] in plain(body), (out['number'],k,e[k])
 key=src['code_id']+'|'+src['source_id']; checks=out.get('reference_checks',[])
 assert [c['target_key'] for c in checks]==r['requirements'][key], out['number']
 for c in checks:
  assert c['view_sha256']==r['targets'][c['target_key']]['view_sha256'] and len(c['assessment'])>=80
print('VALIDATION OK : 24 articles, identifiants, citations, balises, impacts, bénéfices requis et 14 contrôles de renvois.')
print('Statuts :',dict(Counter(x['status'] for x in a)))
print('Impacts :',dict(Counter(x['substantive_impact']['classification'] for x in a)))
print('Taille :',len(open('answer.json').read()),'caractères')
PY"

